public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int H, W;
    static char[][] grid;
    static boolean[][] visited;
    static final int[] dr = {-1, 1, 0, 0};
    static final int[] dc = {0, 0, -1, 1};

    static void dfs(int r, int c, char fruit) {
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{r, c});
        visited[r][c] = true;

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int x = cur[0], y = cur[1];

            for (int k = 0; k < 4; k++) {
                int nx = x + dr[k];
                int ny = y + dc[k];
                if (0 <= nx && nx < H && 0 <= ny && ny < W
                        && !visited[nx][ny] && grid[nx][ny] == fruit) {
                    visited[nx][ny] = true;
                    stack.push(new int[]{nx, ny});
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            String first = fs.next();
            if (first == null) break;
            H = Integer.parseInt(first);
            W = fs.nextInt();

            if (H == 0 && W == 0) break;

            grid = new char[H][];
            for (int i = 0; i < H; i++) {
                grid[i] = fs.next().toCharArray();
            }

            visited = new boolean[H][W];
            int count = 0;

            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (!visited[i][j]) {
                        dfs(i, j, grid[i][j]);
                        count++;
                    }
                }
            }

            out.append(count).append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys
sys.setrecursionlimit(10**6)

def solve():
    data = sys.stdin.read().strip().split()
    idx = 0
    results = []

    while True:
        H = int(data[idx]); W = int(data[idx+1])
        idx += 2
        if H == 0 and W == 0:
            break

        grid = data[idx:idx+H]
        idx += H

        visited = [[False] * W for _ in range(H)]
        count = 0

        # Directions: up, down, left, right
        dirs = [(-1,0),(1,0),(0,-1),(0,1)]

        def dfs(r, c, fruit_type):
            stack = [(r, c)]
            visited[r][c] = True
            while stack:
                x, y = stack.pop()
                for dx, dy in dirs:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny] and grid[nx][ny] == fruit_type:
                        visited[nx][ny] = True
                        stack.append((nx, ny))

        for i in range(H):
            for j in range(W):
                if not visited[i][j]:
                    count += 1
                    dfs(i, j, grid[i][j])

        results.append(str(count))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()

import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    out = []

    for a, b in zip(it, it):
        H = int(a)
        W = int(b)
        if H == 0 and W == 0:
            break

        grid = [list(next(it)) for _ in range(H)]
        visited = [[False] * W for _ in range(H)]
        count = 0

        for i in range(H):
            for j in range(W):
                if visited[i][j]:
                    continue
                count += 1
                ch = grid[i][j]
                q = deque()
                q.append((i, j))
                visited[i][j] = True

                while q:
                    x, y = q.popleft()
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W:
                            if not visited[nx][ny] and grid[nx][ny] == ch:
                                visited[nx][ny] = True
                                q.append((nx, ny))

        out.append(str(count))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
